 35	    private static void quickSort(int[] values, int fromIndex, int toIndex) {
 36	        while (toIndex - fromIndex > INSERTION_SORT_THRESHOLD) {
 37	            Partition partition = partition(values, fromIndex, toIndex, values[selectPivotIndex(values, fromIndex, toIndex)]);
 38	            int leftPartitionSize = partition.lessThanEnd - fromIndex;
 39	            int rightPartitionSize = toIndex - partition.greaterThanStart;
 40	
 41	            if (leftPartitionSize < rightPartitionSize) {
 42	                quickSort(values, fromIndex, partition.lessThanEnd);
 43	                fromIndex = partition.greaterThanStart;
 44	            } else {
 45	                quickSort(values, partition.greaterThanStart, toIndex);
 46	                toIndex = partition.lessThanEnd;
 47	            }
 48	        }
 49	
 50	        insertionSort(values, fromIndex, toIndex);
 51	    }
