 53	    private static Partition partition(int[] values, int fromIndex, int toIndex, int pivotValue) {
 54	        int lessThanBoundary = fromIndex;
 55	        int currentIndex = fromIndex;
 56	        int greaterThanBoundary = toIndex;
 57	
 58	        while (currentIndex < greaterThanBoundary) {
 59	            if (values[currentIndex] < pivotValue) {
 60	                swap(values, lessThanBoundary, currentIndex);
 61	                lessThanBoundary++;
 62	                currentIndex++;
 63	            } else if (values[currentIndex] > pivotValue) {
 64	                greaterThanBoundary--;
 65	                swap(values, currentIndex, greaterThanBoundary);
 66	            } else {
 67	                currentIndex++;
 68	            }
 69	        }
 70	
 71	        return new Partition(lessThanBoundary, greaterThanBoundary);
 72	    }
