 74	    private static int selectPivotIndex(int[] values, int fromIndex, int toIndex) {
 75	        int lastIndex = toIndex - 1;
 76	        int middleIndex = fromIndex + ((toIndex - fromIndex) >>> 1);
 77	        return medianOfThreeIndex(values, fromIndex, middleIndex, lastIndex);
