 82	        int secondValue = values[secondIndex];
 83	        int thirdValue = values[thirdIndex];
 84	
 85	        if (firstValue < secondValue) {
 86	            if (secondValue < thirdValue) {
 87	                return secondIndex;
 88	            }
 89	
 90	            return firstValue < thirdValue ? thirdIndex : firstIndex;
 91	        }
 92	
 93	        if (firstValue < thirdValue) {
